package hu.taliann.icesmp.playerprofile.persistence;
import hu.taliann.icesmp.playerprofile.domain.*;import java.time.Instant;import java.util.*;
public record PlayerProfileManifest(UUID playerId,String format,int schema,long profileRevision,Instant createdAt,Instant updatedAt,Map<ProfileSectionId,SectionRevision> sections,String lifecycleStatus,Map<String,String> recoveryMetadata){
 public static final String FORMAT="ICESMP-PLAYER-PROFILE";public static final int SCHEMA=1;
 public PlayerProfileManifest{Objects.requireNonNull(playerId);format=Objects.requireNonNull(format);if(!FORMAT.equals(format))throw new IllegalArgumentException("unsupported profile format");if(schema!=SCHEMA)throw new IllegalArgumentException("unsupported profile schema");if(profileRevision<0)throw new IllegalArgumentException("negative profile revision");Objects.requireNonNull(createdAt);Objects.requireNonNull(updatedAt);if(updatedAt.isBefore(createdAt))throw new IllegalArgumentException("invalid timestamps");EnumMap<ProfileSectionId,SectionRevision> copy=new EnumMap<>(ProfileSectionId.class);copy.putAll(sections==null?Map.of():sections);sections=Collections.unmodifiableMap(copy);lifecycleStatus=lifecycleStatus==null?"active":lifecycleStatus.trim();recoveryMetadata=recoveryMetadata==null?Map.of():Map.copyOf(recoveryMetadata);}
 public static PlayerProfileManifest from(PlayerProfileSnapshot p){return new PlayerProfileManifest(p.playerId(),FORMAT,SCHEMA,p.profileRevision(),p.createdAt(),p.updatedAt(),p.sectionRevisions(),p.health().status().name().toLowerCase(Locale.ROOT),Map.of());}
}
